   [new(Ally,Hp:20){StartingHand=[]}],new string('b',64));
  var game=GameEngine.CreateStandard(new(){Seed=setup.BattleSeed,PlayerCount=4,HumanSeat=0,HumanRole=null,HumanTeamId=ShanheBattleSetup.PlayerTeamId,ModeId=ShanheBattleSetup.BattleModeId,ShanheBattle=setup,UseInteractiveSetup=false,UseInteractiveDiscard=false,AdvanceAfterHumanCommands=false,MaxTurns=18},registry);
  PendingDecision? P()=>Enumerable.Range(0,4).Select(s=>game.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p is not null);
  PlayerSnapshot V(int seat=0)=>game.CreateSnapshot(0).Players[seat];T[] E<T>()=>game.Events.Select(e=>e.Payload).OfType<T>().ToArray();
  ProgramSkillFrame? F()=>game.ResolutionStack.OfType<ProgramSkillFrame>().LastOrDefault(f=>f.MouChengYuAnniversary is not null);MouCyReceipt? R()=>F()?.MouChengYuAnniversary;
  string Diagnostic()=>JsonSerializer.Serialize(new{game.State.TurnNumber,game.State.CurrentSeat,game.State.Phase,Prompt=P(),Receipt=R(),Players=game.CreateSnapshot(0).Players.Select(p=>new{p.Seat,p.GeneralId,p.Hp,p.HandCount,p.Equipment}),Frames=game.ResolutionStack.Select(f=>JsonSerializer.Serialize(f,f.GetType())),Facts=game.Events.TakeLast(35).Select(e=>JsonSerializer.Serialize(e.Payload,e.Payload.GetType()))});
  void Need(bool yes,string why){if(!yes)throw new InvalidOperationException(why+Diagnostic());}
  void Submit(GameCommand c){try{var result=game.Submit(CommandJson.Deserialize(CommandJson.Serialize([c])).Single());Need(result.Accepted,result.Error?.Message??"Native command rejected.");}catch(Exception ex){throw new InvalidOperationException(ex.Message+Diagnostic(),ex);}}
  void Answer(Func<PromptChoice,bool> match){var p=P();Need(p?.PlayerSeat==0,"Only the actual published Human chooser answers.");var choice=p!.Choices.FirstOrDefault(match);Need(choice is not null,"The exact current native choice is published.");Submit(new AnswerPromptCommand(0,p.PromptId,choice!.Id,game.Revision));}
  void Reach(Func<bool> done,[CallerLineNumber]int line=0)
  {
   for(var i=0;i<160;i++){if(done())return;Need(game.State.Winner==Winner.None,"Unexpected terminal boundary at "+line);if(P()is{PlayerSeat:0}p){if(p.Kind is DecisionKind.Nullification or DecisionKind.RespondSlash or DecisionKind.RespondDodge){Answer(c=>c.Parameters.GetValueOrDefault("response")is"pass"or"take-damage");continue;}throw new InvalidOperationException("Unexpected actual Human boundary at "+line+Diagnostic());}Submit(new AdvanceOneStepCommand(game.Revision));}throw new InvalidOperationException("Bounded actual Cheng Yu flow not reached at "+line+Diagnostic());
  }
  void Play()=>Reach(()=>P()is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
  void Active(string skill,string action,IReadOnlyList<int>? cards=null,IReadOnlyList<int>? targets=null)=>Submit(new UseProgramSkillCommand(0,skill,action,cards??[],targets??[],game.Revision,P()!.PromptId));
  void Card(int id,IReadOnlyList<int> targets){var a=game.GetHumanLegalActions().FirstOrDefault(a=>a.CardId==id&&a.ConversionSource is null&&a.TargetSeats.SequenceEqual(targets));Need(a is not null,"The exact real Hand entity has its native use action.");Submit(new PlayCardCommand(0,id,a!.TargetSeats,game.Revision,P()!.PromptId,a.PlayedCardKind,a.TargetCardId));}
