   var hp=V(1).Hp;Active(Driver,"wound",targets:[1]);Reach(()=>P()?.SkillPrompt?.SkillId=="mou:shizha"&&P()!.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="activate"));Need(V(1).Hp==hp-1,"Another living role's actual HP change reaches Shizha's owner; the owner is not substituted as the HP victim.");Answer(c=>c.Parameters.GetValueOrDefault("program-action")=="activate");Reach(()=>R()?.Stage==MouCyStage.Peek&&P()?.PlayerSeat==0);
  }
  (long FrameId,int CardId) Pick(CardKind kind){var id=F()!.Id;var card=R()!.View.First(c=>c.Kind==kind);var before=R()!.Before;Answer(c=>c.Cards.SequenceEqual([card.Id]));Play();Need(game.CreateSnapshot(0).Players[0].NamedAmbushPiles?.Any(p=>p.SkillId=="mou:shizha"&&p.Entries?.Any(e=>e.Card.Id==card.Id&&e.RecordedKind==kind)==true)==true&&game.CardMovements.Count(m=>m.CardId==card.Id&&m.From==CardLocation.DrawPile&&m.To==CardLocation.Hand(0)&&m.Sequence>before)==1,"The recorded private name is paid by the exact real viewed deck obtain, not a simulated draw or Hand-count change.");return(id,card.Id);}
  void NextPlay(){var turn=game.State.TurnNumber;Submit(new EndPlayPhaseCommand(0,game.Revision,P()!.PromptId));Play();Need(game.State.TurnNumber>turn&&E<TurnEndedEvent>().Any(e=>e.ActorSeat==0&&e.TurnNumber==turn),"The next allowance follows a real completed actual turn and native turn progression.");}
  Submit(new StartGameCommand());Play();Need(V().GeneralId==Hero&&V(1).GeneralId==Ally&&V(2).GeneralId==Enemy&&V().Equipment.Single().Kind==CardKind.QilinBow&&game.GetAttackRange(0)==5,"The fixed native roster preserves the intended actor, Hand-response role and real range-five weapon.");
  var nullCard=V().Hand.Single(c=>c.Kind==CardKind.Nullification).Id;var duel=V().Hand.Single(c=>c.Kind==CardKind.Duel).Id;var slashFire=V().Hand.First(c=>c.Kind==CardKind.Slash).Id;var slashUse=V().Hand.Last(c=>c.Kind==CardKind.Slash).Id;var equipment=V().Hand.Single(c=>c.Kind==CardKind.Crossbow).Id;var drawTwo=V().Hand.Single(c=>c.Kind==CardKind.DrawTwo).Id;
  Top(nullCard);WoundToPeek();var viewed=R()!.View.Select(c=>c.Id).ToArray();Need(viewed.Length==3&&viewed[0]==nullCard&&game.CreateSnapshot(0).PrivateRevealedCards?.Select(c=>c.Id).Order().SequenceEqual(viewed.Order())==true&&(game.CreateSnapshot(2).PrivateRevealedCards?.Count??0)==0,"Only the owner privately sees the exact real top three; the topdecked Nullification keeps its real first position.");
  var before=SnapshotJson.Serialize(game.CreateSnapshot(0));var other=SnapshotJson.Serialize(game.CreateSnapshot(2));game=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(game.CreateCheckpoint())),registry);
  Need(before==SnapshotJson.Serialize(game.CreateSnapshot(0))&&other==SnapshotJson.Serialize(game.CreateSnapshot(2))&&R()is{Stage:MouCyStage.Peek}&&R()!.View.Select(c=>c.Id).SequenceEqual(viewed)&&(game.CreateSnapshot(0).Players[0].NamedAmbushPiles?.All(p=>p.SkillId!="mou:shizha")??true),"One representative Cold preserves the actual HP parent and private top selection without prematurely moving or recording a card.");
  var nullRecord=Pick(CardKind.Nullification);var privateNames=game.CreateSnapshot(0).Players[0].NamedAmbushPiles?.Single(p=>p.SkillId=="mou:shizha");var publicNames=game.CreateSnapshot(2).Players[0].NamedAmbushPiles?.Single(p=>p.SkillId=="mou:shizha");Need(privateNames?.Entries is[{RecordedKind:CardKind.Nullification}]&&publicNames is{Count:1,Entries:null}&&viewed.Skip(1).All(id=>!game.CardMovements.Any(m=>m.CardId==id&&m.From==CardLocation.DrawPile)),"The secret name is owner-visible while the unselected real deck entities remain unmoved and hidden.");
  Card(duel,[2]);Reach(()=>R()is{Stage:MouCyStage.Invalidate,Use:{Response:true,Action:{EffectiveKind:CardKind.Nullification,ActorSeat:2}}});var counter=R()!.Use!;Need(E<MouCyNameConsumedEvent>().Count(e=>e.RecordFrameId==nullRecord.FrameId&&e.ActionId==counter.Action.ActionId)==1&&!E<MouCyUseInvalidatedEvent>().Any(),"A genuine paid opposing Counterspell consumes the matching secret name before the optional ineffective choice.");Answer(c=>c.Parameters.GetValueOrDefault("branch")=="invalidate");Play();Need(E<MouCyUseInvalidatedEvent>().Count(e=>e.Use.Action.ActionId==counter.Action.ActionId)==1&&E<DamageAppliedEvent>().Any(e=>e.SourceSeat==0&&e.TargetSeat==2&&e.Amount==1)&&game.CardMovements.Count(m=>counter.Action.PhysicalCards.Any(c=>c.CardId==m.CardId)&&m.From==CardLocation.Hand(2)&&m.To==CardLocation.Processing)==1,"The original paid Counterspell is made ineffective through its native chain, so the genuine Duel damages its intended role; the response entity is not paid twice.");
  Top(slashFire);Active("mou:gaojian","reveal-and-advise");Reach(()=>R()?.Stage==MouCyStage.Target);Answer(c=>c.Targets.SequenceEqual([2]));Play();var fireReveal=E<MouCyRevealedEvent>().Single();Need(fireReveal.CardId==slashFire&&fireReveal.Count==1&&E<DamageAppliedEvent>().Any(e=>e.SourceSeat==0&&e.TargetSeat==2&&e.Nature==DamageNature.Fire&&e.Amount==1)&&game.CardMovements.Count(m=>m.CardId==slashFire&&m.From==CardLocation.DrawPile&&m.To==CardLocation.Processing)==1&&game.CardMovements.Count(m=>m.CardId==slashFire&&m.From==CardLocation.Processing&&m.To==CardLocation.DiscardPile)==1,"Gaojian publicly reveals the exact top damage card, requests real owner-sourced fire damage of the actual reveal count, then retires that same physical card once.");
  NextPlay();WoundToPeek();var dodgeRecord=Pick(CardKind.Dodge);var hpBefore=V(2).Hp;Card(slashUse,[2]);Reach(()=>R()is{Stage:MouCyStage.Invalidate,Use:{Response:true,Action:{EffectiveKind:CardKind.Dodge,ActorSeat:2}}});var dodge=R()!.Use!;Answer(c=>c.Parameters.GetValueOrDefault("branch")=="invalidate");Play();Need(V(2).Hp==hpBefore-1&&E<MouCyNameConsumedEvent>().Count(e=>e.RecordFrameId==dodgeRecord.FrameId&&e.ActionId==dodge.Action.ActionId)==1&&E<MouCyUseInvalidatedEvent>().Count(e=>e.Use.Action.ActionId==dodge.Action.ActionId)==1&&game.CardMovements.Count(m=>dodge.Action.PhysicalCards.Any(c=>c.CardId==m.CardId)&&m.From==CardLocation.Hand(2)&&m.To==CardLocation.Processing)==1,"A genuine Slash-Dodge Use is made ineffective and resumes the original incoming Slash damage; a normal played response is never fabricated into this Use.");
  var range=game.GetAttackRange(0);Active("mou:gaojian","reveal-and-advise");Reach(()=>R()?.Stage==MouCyStage.Target);Answer(c=>c.Targets.SequenceEqual([0]));Reach(()=>R()is{Stage:MouCyStage.RevealChoice,RevealCount:1});var gained=R()!.CardId;Answer(c=>c.Parameters.GetValueOrDefault("branch")=="gain");Reach(()=>R()is{Stage:MouCyStage.RevealChoice,RevealCount:2});var rejected=R()!.CardId;Answer(c=>c.Parameters.GetValueOrDefault("branch")=="range");Play();Need(V().Hand.Any(c=>c.Id==gained)&&game.CardMovements.Count(m=>m.CardId==gained&&m.From==CardLocation.Processing&&m.To==CardLocation.Hand(0))==1&&game.CardMovements.Count(m=>m.CardId==rejected&&m.From==CardLocation.Processing&&m.To==CardLocation.DiscardPile)==1&&E<MouCyRangeIssuedEvent>()is[{Target:0,Amount:2}]&&game.GetAttackRange(0)==range-2,"The actual target obtains the first non-damage reveal and makes its own second-reveal choice; X counts both real reveals and subtracts from the real weapon range until that role's own turn ends.");
  NextPlay();Need(game.GetAttackRange(0)==range,"The self-target range penalty expires at the actual native TurnEnded boundary.");Top(equipment);WoundToPeek();var gearRecord=Pick(CardKind.Crossbow);Card(equipment,[]);Reach(()=>R()is{Stage:MouCyStage.Invalidate,Use:{Response:false,Action:{EffectiveKind:CardKind.Crossbow,ActorSeat:0}}});var gearUse=R()!.Use!;Answer(c=>c.Parameters.GetValueOrDefault("branch")=="invalidate");Play();Need(V().Equipment is[{Kind:CardKind.QilinBow}]&&game.CardMovements.Count(m=>m.CardId==equipment&&m.From==CardLocation.Hand(0)&&m.To==CardLocation.Processing)==1&&game.CardMovements.Count(m=>m.CardId==equipment&&m.From==CardLocation.Processing&&m.To==CardLocation.DiscardPile)==1&&!game.CardMovements.Any(m=>m.CardId==equipment&&m.To==CardLocation.Equipment(0))&&E<MouCyNameConsumedEvent>().Count(e=>e.RecordFrameId==gearRecord.FrameId)==1&&E<CardUseFinishedEvent>().Count(e=>e.ResolutionId==gearUse.ParentId&&e.CardId==equipment)==1,"An exact matching own Equipment Use is intercepted before installation, spends the native material once and finishes once without replacing the original weapon or borrowing another skill's invalidation proof.");
  NextPlay();Top(drawTwo);WoundToPeek();var drawRecord=Pick(CardKind.DrawTwo);var hand=V().HandCount;Card(drawTwo,[]);Reach(()=>R()is{Stage:MouCyStage.Invalidate,Use:{Response:false,Action:{EffectiveKind:CardKind.DrawTwo}}});var drawAction=R()!.Use!.Action.ActionId;Answer(c=>c.Parameters.GetValueOrDefault("branch")=="decline");Play();Need(V().HandCount==hand+1&&E<MouCyNameConsumedEvent>().Count(e=>e.RecordFrameId==drawRecord.FrameId&&e.ActionId==drawAction)==1&&!E<MouCyUseInvalidatedEvent>().Any(e=>e.Use.Action.ActionId==drawAction)&&(game.CreateSnapshot(0).Players[0].NamedAmbushPiles?.All(p=>p.SkillId!="mou:shizha")??true),"Declining the optional ineffective choice still consumes the secret name; the same genuine DrawTwo keeps its native two-card draw and no ineffective receipt is forged.");
